<?php get_header(); $author = get_queried_object(); ?><main id="main-content" class="site-main container section-space"><header class="author-header"><?php echo get_avatar( $author->ID, 112 ); ?><div><p class="eyebrow"><?php esc_html_e( 'Author', 'meridian-news' ); ?></p><h1><?php echo esc_html( $author->display_name ); ?></h1><?php if ( $author->description ) { ?><p><?php echo esc_html( $author->description ); ?></p><?php } ?><?php if ( $author->user_url ) { ?><a class="text-link" href="<?php echo esc_url( $author->user_url ); ?>"><?php esc_html_e( 'Website', 'meridian-news' ); ?></a><?php } ?></div></header><?php if ( have_posts() ) : ?><div class="card-grid"><?php while ( have_posts() ) : the_post(); get_template_part( 'template-parts/content', 'card' ); endwhile; ?></div><?php meridian_news_pagination(); else : ?><div class="empty-state"><h2><?php esc_html_e( 'No articles yet', 'meridian-news' ); ?></h2></div><?php endif; ?></main><?php get_footer(); ?>
